import { z } from "zod";
export const documentSchema=z.object({documentType:z.enum(["or_cr","driver_license","mtop_franchise","insurance"]),unitId:z.string().uuid().optional(),driverId:z.string().uuid().optional(),documentNumber:z.string().max(120).optional(),issuedOn:z.string().optional(),expiresOn:z.string(),mimeType:z.enum(["image/jpeg","image/png","image/webp","application/pdf"]),sizeBytes:z.number().int().positive().max(5242880),sha256:z.string().regex(/^[a-f0-9]{64}$/),objectPath:z.string()}).refine(v=>Boolean(v.unitId!==undefined||v.driverId!==undefined),"Choose a holder");
