"use server";
import { randomUUID } from "node:crypto"; import { revalidatePath } from "next/cache"; import { createSupabaseServerClient } from "@/lib/supabase/server"; import { requirePermission } from "@/lib/auth/guards"; import { documentSchema } from "@/lib/validation/documents";
export async function prepareDocumentUpload(input:{documentType:string;unitId?:string;driverId?:string;filename:string;mimeType:string}){await requirePermission("manage_documents");if(!["image/jpeg","image/png","image/webp","application/pdf"].includes(input.mimeType))throw new Error("Unsupported document type");const id=randomUUID();const ext=input.mimeType==='application/pdf'?'pdf':input.mimeType.split('/')[1];return {documentId:id,objectPath:`documents/${id}/${randomUUID()}.${ext}`};}
export async function finalizeDocumentUpload(input:unknown){await requirePermission("manage_documents");const v=documentSchema.parse(input);const s=await createSupabaseServerClient();if(v.documentType==='driver_license'&&v.driverId){const {data:driver}=await s.from("drivers").select("license_expiry_date").eq("id",v.driverId).maybeSingle();if(driver?.license_expiry_date!==v.expiresOn)throw new Error("License document expiry must match the driver profile");}const {data,error}=await s.from("documents").insert({document_type:v.documentType,unit_id:v.unitId??null,driver_id:v.driverId??null,document_number:v.documentNumber??null,issued_on:v.issuedOn??null,expires_on:v.expiresOn,lifecycle_status:"current",object_path:v.objectPath,mime_type:v.mimeType,size_bytes:v.sizeBytes,sha256:v.sha256}).select().single();if(error)throw new Error("Could not save document");revalidatePath("/documents");return data;}
export async function getDocumentUrl(path:string){await requirePermission("manage_documents");const s=await createSupabaseServerClient();const {data,error}=await s.storage.from("documents").createSignedUrl(path,300);if(error)throw new Error("Could not create document link");return data.signedUrl;}
export async function softDeleteDocument(id:string){await requirePermission("manage_documents");const s=await createSupabaseServerClient();await s.from("documents").update({deleted_at:new Date().toISOString(),lifecycle_status:"void"}).eq("id",id);revalidatePath("/documents");}
